from lib import *
S = SS('k37')
F1 = [['minAvailable: 2', 'allowed 3'], ['minAvailable: 50%', 'desired 3 → allowed 2'], ['maxUnavailable: 1', 'allowed 1'], ['maxUnavailable: 50%', 'allowed 3'], ['minAvailable: 100%', 'allowed 0']]
F2 = [['驱逐 #1', '201'], ['驱逐 #2', '429 TooManyRequests'], ['替代 Pod 就绪', '6.0 s'], ['允许数恢复', '1']]
F3 = [['drain worker2', '2 个 Pod'], ['第 1 个驱逐成功', ''], ['第 2 个 429', 'will retry after 5s'], ['6 秒后完成', ''], ['kubectl delete pod ×2', 'PDB 拦不住']]
F4 = [['IfHealthyBudget', '不健康的 Pod 也要看预算 → 429'], ['AlwaysAllow', '不健康的 Pod 随时可驱逐 → 201']]
PANELS = [('f', 'flow', 'PDB 与驱逐'), ('t', 'term', '实测输出'), ('kv', 'kv', '要点')]
steps = [
    step("5 个健康的 Pod,不同写法的 PDB:minAvailable: 2 → desiredHealthy=2、disruptionsAllowed=3;minAvailable: \"50%\" → desiredHealthy=3(2.5 向上取整)、allowed=2;maxUnavailable: 1 → desiredHealthy=4、allowed=1;maxUnavailable: \"50%\" → desiredHealthy=2、allowed=3;minAvailable: \"100%\" → desiredHealthy=5、allowed=0。", f=fl(F1, cur=[1, 3], mark=[4]), t=tl(S(1), mark=lidx(S(1), '50%', '100%'), done=lidx(S(1), 'minAvailable: 2 ', 'maxUnavailable: 1')), kv=KV([['minAvailable', '至少要保留几个(百分比向上取整)'], ['maxUnavailable', '最多能少几个(百分比向上取整)'], ['100%', '一个都不让动,drain 会一直卡住']], ['100%'])),
    step("3 个 Pod、minAvailable: 2:currentHealthy=3、desiredHealthy=2、disruptionsAllowed=1。Eviction API:驱逐第 1 个 → 201 Success;紧接着驱逐第 2 个 → TooManyRequests:Cannot evict pod as it would violate the pod's disruption budget.,此时 currentHealthy=2、disruptionsAllowed=0;Deployment 补出的新 Pod(就绪探针 initialDelaySeconds=5)就绪后,从第 1 次驱逐算起 6.0 秒,disruptionsAllowed 恢复为 1,可以再驱逐一个。", f=fl(F2, cur=[1], done=[0, 2, 3]), t=tl(S(2), mark=lidx(S(2), 'TooManyRequests', '此时 PDB'), done=lidx(S(2), '驱逐第 1 个', '6.0 秒', '现在再驱逐')), kv=KV([['预算用完', 'Eviction 返回 429,调用方要自己重试'], ['恢复', '要等替代的 Pod 真的就绪'], ['disruptionsAllowed', '= currentHealthy − desiredHealthy']], ['预算用完'])),
    step("kubectl drain worker2(上面有 2 个 web Pod):cordoned → 同时对两个 Pod 发起 evicting → 第 1 个 evicted;第 2 个报 error when evicting … (will retry after 5s): Cannot evict pod as it would violate the pod's disruption budget.,重试成功后 drained,一共用了 6 秒。对比:kubectl delete pod 一次删掉 2 个,不经过 Eviction API,PDB 拦不住:0.5 秒后 ready 的 Pod 只剩 1 个,PDB 变成 currentHealthy=1、desiredHealthy=2、allowed=0。", f=fl(F3, cur=[1, 2], done=[0, 3], mark=[4]), t=tl(S(3), mark=lidx(S(3), 'will retry after 5s', 'delete pod 一次删掉 2 个'), done=lidx(S(3), 'drained', 'cordoned')), kv=KV([['drain', '用 Eviction API,被 PDB 拦住就每 5 秒重试'], ['kubectl delete pod', '不是驱逐,PDB 不起作用'], ['PDB 只保护自愿中断', '节点宕机等非自愿中断它管不了']], ['kubectl delete pod'])),
    step("Pod 本身不健康时:3 个 Pod 里 1 个就绪探针失败、minAvailable: 3,PDB 是 currentHealthy=2、desiredHealthy=3、allowed=0。unhealthyPodEvictionPolicy=IfHealthyBudget(默认)时驱逐那个不健康的 Pod → TooManyRequests;AlwaysAllow 时 → 201,不健康的 Pod 随时可以被驱逐。", f=fl(F4, cur=[0, 1]), t=tl(S(4), mark=lidx(S(4), 'TooManyRequests'), done=lidx(S(4), 'code=201')), kv=KV([['IfHealthyBudget', '预算健康时才能驱逐不健康的 Pod'], ['AlwaysAllow', '不健康的 Pod 一律允许驱逐'], ['卡住的 drain', '常见原因:Pod 一直不就绪 + 默认策略']], ['AlwaysAllow'])),
]
A = mkartk('k37', 37, 'Kubernetes,PodDisruptionBudget,PDB,驱逐,drain,Eviction API,真实验证,动画演示',
    '在 kind 集群里实测 PodDisruptionBudget:5 个 Pod 下 minAvailable 2 / 50% / maxUnavailable 1 / 50% / 100% 分别允许中断 3 / 2 / 1 / 3 / 0 个(百分比向上取整);Eviction API 在预算用完时返回 429 TooManyRequests,替代 Pod 就绪(6.0 秒)后才恢复;kubectl drain 被 PDB 拦住时每 5 秒重试、共用 6 秒,而 kubectl delete pod 绕过 PDB;unhealthyPodEvictionPolicy 为 AlwaysAllow 时不健康的 Pod 可以被驱逐,默认的 IfHealthyBudget 则返回 429。',
    'PDB 到底保护了什么?drain 的时候它是怎么起作用的?为什么 kubectl delete pod 拦不住?这篇用 Eviction API 直接发请求,看 allowed 数怎么算、429 长什么样、drain 怎么重试,以及不健康的 Pod 在两种策略下的不同命运。',
    [('429 → 6.0 秒', '预算用完时 Eviction API 的返回,以及替代 Pod 就绪后预算恢复所用的时间'), ('50% of 5 → 3 / 2', 'minAvailable: "50%" 时 desiredHealthy 为 3(向上取整)、允许中断 2 个'), ('IfHealthyBudget vs AlwaysAllow', '同一个不健康的 Pod,驱逐请求分别返回 429 与 201')],
    [('PDB 怎么算', '<p>PDB 的 status 里 <code>disruptionsAllowed = currentHealthy − desiredHealthy</code>。同样 5 个健康 Pod:<code>minAvailable: 2</code> 允许 3 个;<code>minAvailable: "50%"</code> 的 <code>desiredHealthy</code> 是 3(2.5 向上取整),允许 2 个;<code>maxUnavailable: 1</code> 允许 1 个;<code>maxUnavailable: "50%"</code> 允许 3 个;<code>minAvailable: "100%"</code> 一个都不让动。写成 100% 的 PDB 会让节点 drain 永远卡住。</p>'),
     ('Eviction API', '<p>3 个 Pod、<code>minAvailable: 2</code>(允许 1 个)。直接调 Eviction API:第 1 次 <code>201</code>;紧接着第 2 次 <code>TooManyRequests: Cannot evict pod as it would violate the pod\'s disruption budget.</code>。这时 <code>currentHealthy=2</code>、<code>disruptionsAllowed=0</code>,要等 Deployment 补出的新 Pod 真的 Ready(这里就绪探针延迟 5 秒,总共 6.0 秒)预算才恢复,再驱逐才会成功。429 是让调用方重试,不是失败。</p>'),
     ('drain 与 delete', '<p><code>kubectl drain</code> 对节点上的 2 个 Pod 同时发起驱逐:第 1 个成功,第 2 个被 PDB 拦住,输出 <code>error when evicting … (will retry after 5s)</code>,5 秒后重试成功,一共 6 秒。而 <code>kubectl delete pod</code> 一次删 2 个不是驱逐,PDB 拦不住:0.5 秒后只剩 1 个 Ready,PDB 变成 <code>currentHealthy=1 < desiredHealthy=2</code>。PDB 只约束自愿中断(驱逐),节点宕机、直接删除这类它管不了。</p>'),
     ('不健康的 Pod', '<p>3 个 Pod 里 1 个就绪探针失败、<code>minAvailable: 3</code>:<code>currentHealthy=2</code>,<code>disruptionsAllowed=0</code>。默认的 <code>unhealthyPodEvictionPolicy: IfHealthyBudget</code> 下,连这个不健康的 Pod 也驱逐不了(429),drain 会一直卡;改成 <code>AlwaysAllow</code> 之后不健康的 Pod 随时可以驱逐(201),应用本来就坏了,没必要再为它保留名额。</p>')],
    steps,
    [ENV_K + '。三节点 kind 集群 kx-main(Kubernetes v1.37.0);两个 worker 打上标签 k37=yes,Deployment 用 nodeSelector 只放在它们上面;Eviction API 用 kubectl create --raw /api/v1/namespaces/<ns>/pods/<pod>/eviction 直接请求;第 2、3 节的就绪探针用 initialDelaySeconds=5 让替代 Pod 需要几秒才就绪(没有这个延迟时替代 Pod 0.4 秒就就绪,drain 里看不到重试);kubectl drain 带 --ignore-daemonsets --delete-emptydir-data --force,结束后 uncordon;实验后删除了节点标签与命名空间;每种情形各一次',
     '没有验证:PDB 的 selector 为空或匹配到带 ownerReferences 的非标准控制器时 expectedPods 的计算;一个 Pod 被多个 PDB 选中时的错误;抢占对 PDB 的遵守程度;节点自动伸缩(cluster-autoscaler)对 PDB 的使用;drain 的 --disable-eviction 与 --grace-period;PDB 对 Pod 级别 DisruptionTarget 条件的关系'],
    'PDB 与驱逐', PANELS)
